from flask import request, jsonify

@app.get('/items')
def list_items():
    try:
        page = int(request.args.get('page', '1'))
        page_size = int(request.args.get('page_size', '20'))
        if page < 1 or page_size < 1:
            raise ValueError
    except ValueError:
        return jsonify(error='page and page_size must be positive integers'), 400

    page_size = min(page_size, 100)
    offset = (page - 1) * page_size
    # Reuse the existing SQLite connection helper.
    db = get_db()
    cursor = db.execute(
        'SELECT * FROM items ORDER BY id LIMIT ? OFFSET ?',
        (page_size, min(offset, 9223372036854775807)),
    )
    columns = [column[0] for column in cursor.description]
    items = [dict(zip(columns, row)) for row in cursor.fetchall()]
    return jsonify(items=items, page=page, page_size=page_size)
